import io
io.open("/tmp/job.sh","w").write('set -e\nexport PYTHONUNBUFFERED=1 WANDB_MODE=disabled WANDB_DISABLED=true HF_HUB_OFFLINE=1\nwhich git >/dev/null 2>&1 || (apt-get update -q && apt-get install -y -q git) >/dev/null 2>&1\ncd /tmp && rm -rf po && git clone --depth 1 https://github.com/camlab-ethz/poseidon po 2>&1 | tail -1\ncd /tmp/po\npip install -q -e . --no-deps 2>&1 | tail -1\npip install -q transformers==4.29.2 accelerate==0.31.0 "huggingface_hub<0.20" wandb einops timm netCDF4 h5py pandas pyyaml matplotlib safetensors psutil 2>&1 | tail -1\npython - <<\'P1\'\nimport re\nfor pyf, oldmax, nmax in [("scOT/problems/fluids/incompressible.py","20000","2354"),\n                          ("scOT/problems/reaction_diffusion/allen_cahn.py","15000","3750"),\n                          ("scOT/problems/wave/acoustic.py","10512","3504")]:\n    s = open(pyf).read()\n    s = s.replace(f"{oldmax},", f"{nmax},")\n    s = re.sub(r"self\\.N_max\\s*=\\s*\\d+", f"self.N_max = {nmax}", s)\n    s = re.sub(r"self\\.N_val\\s*=\\s*\\d+", "self.N_val = 64", s)\n    s = re.sub(r"self\\.N_test\\s*=\\s*\\d+", "self.N_test = 128", s)\n    open(pyf, "w").write(s)\nprint("SPLIT PATCHES OK")\nP1\ncp /tmp/scot_ourmetric2.py .\nB() { CJ=$(find "$1" -name config.json 2>/dev/null | grep -v checkpoint- | head -1); [ -z "$CJ" ] && CJ=$(find "$1" -path "*checkpoint-*/config.json" 2>/dev/null | sort -t- -k2 -n | tail -1); dirname "$CJ"; }\nNS=$(B /eu/results/scot_ft_ckpt/NS-PwC_64_velx4); echo NS=$NS\nWV=$(B /eu/results/scot_ft_ckpt/Wave-Layer_64_x4); echo WV=$WV\nAC=$(B /eu/results/scot_ft_ckpt/ACE_64); echo AC=$AC\nfor T0 in 0 1 2 4 8; do\n  echo "=== NS-x4 T0=$T0 ==="; DATA=/eu/data/poseidon/_assembled python -u scot_ourmetric2.py "$NS" fluids.incompressible.PiecewiseConstants $T0 20 0:2 time \'{"just_velocities": true}\' | tail -1\n  echo "=== Wave-x4b T0=$T0 ==="; DATA=/eu/data/poseidon/_scot python -u scot_ourmetric2.py "$WV" wave.Layer $T0 20 0:1 time | tail -1\n  echo "=== ACE@3200 T0=$T0 ==="; DATA=/eu/data/poseidon/_assembled python -u scot_ourmetric2.py "$AC" reaction_diffusion.AllenCahn $T0 19 0:1 time | tail -1\ndone\necho ASWEEP_DONE\n')
io.open("/tmp/scot_ourmetric2.py","w").write('"""Generic fair-metric scorer for finetuned scOT ckpts: per-sample rel-L1 on the QoI channels in PHYSICAL\nspace, median over samples of mean over frames (our routine). Args: model_dir ds_string T0 FT qoi mode kw"""\nimport sys, os, json, numpy as np\nsys.path.insert(0, os.getcwd())\nfrom scOT.inference import get_trainer, rollout, get_test_set\n\nmodel_path, ds, T0, FT, qoi, mode = sys.argv[1], sys.argv[2], int(sys.argv[3]), int(sys.argv[4]), sys.argv[5], sys.argv[6]\nKW = json.loads(sys.argv[7]) if len(sys.argv) > 7 else {}\nDATA = os.environ["DATA"]\nq0, q1 = [int(x) for x in qoi.split(":")]\n\ndef denorm(arr, ts):\n    c = ts.constants\n    if "mean_solution" in c:\n        m = np.array(float(c["mean_solution"])); s = np.array(float(c["std_solution"]))\n        return arr[:, q0:q1] * s + m\n    m = np.asarray(c["mean"], dtype=np.float64).reshape(-1); s = np.asarray(c["std"], dtype=np.float64).reshape(-1)\n    if m.size == 1:\n        return arr[:, q0:q1] * s.item() + m.item()\n    return arr[:, q0:q1] * s[q0:q1, None, None] + m[q0:q1, None, None]\n\ndef relL1(p, r):\n    return np.abs(p - r).sum(axis=(1, 2, 3)) / (np.abs(r).sum(axis=(1, 2, 3)) + 1e-12)\n\ntrainer = None; E = []\nif mode == "steady":\n    ts = get_test_set(ds, DATA, dataset_kwargs=KW)\n    trainer = get_trainer(model_path, 16, ts, workers=2)\n    out = rollout(trainer, ts, ar_steps=1)\n    e = relL1(denorm(out[0].astype(np.float64), ts), denorm(out[1].astype(np.float64), ts))\n    E.append(e)\nelse:\n    for t in range(T0 + 1, FT + 1):\n        ts = get_test_set(ds, DATA, initial_time=T0, final_time=t, dataset_kwargs=KW)\n        if trainer is None:\n            trainer = get_trainer(model_path, 16, ts, workers=2)\n        out = rollout(trainer, ts, ar_steps=1)\n        e = relL1(denorm(out[0].astype(np.float64), ts), denorm(out[1].astype(np.float64), ts))\n        E.append(e)\n        print(f"  t={t}: median={np.median(e)*100:.3f}%", flush=True)\nE = np.stack(E)\nprint(f"OURMETRIC2 ds={ds} model={model_path} T0={T0}: median_of_means={np.median(E.mean(axis=0))*100:.3f}%  "\n      f"mean_of_medians={np.mean(np.median(E, axis=1))*100:.3f}%  final={np.median(E[-1])*100:.3f}%", flush=True)\n')
print("STAGED")
